var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    try {
      ms(null);
      assert.fail('Expected error');
    } catch (err) {
      assert.strictEqual(err.message, 'null');
    }
    try {
      ms(undefined);
      assert.fail('Expected error');
    } catch (err) {
      assert.strictEqual(err.message, 'undefined');
    }
    try {
      ms('');
      assert.fail('Expected error');
    } catch (err) {
      assert.strictEqual(err.message, '""');
    }
    try {
      ms('invalid');
      assert.fail('Expected error');
    } catch (err) {
      assert.strictEqual(err.message, 'invalid');
    }
  });
});

